list_cities.code:
import (
	"fmt"
)

resp, err := client.Cities().ListCities(ctx, map[string]any{"country": "AU", "state": "VIC", "limit": 20}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["cities"].([]any) {
	city := row.(map[string]any)
	fmt.Println(city["id"], city["name"], city["post_code"], city["state"].(map[string]any)["code"])
}
pagination := body["pagination"].(map[string]any)
fmt.Println(pagination["total"], pagination["has_next"])

